import java.util.*;
import java.io.*;

public class E {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String inputStr = scanner.next();
        int length = inputStr.length();

        if (length < 2) {
            if (inputStr.equals("0") || inputStr.equals("_") || inputStr.equals("X")) {
                System.out.println(1);
            } else {
                System.out.println(0);
            }
            return;
        }

        if (length == 2) {
            int totalCount = 0;
            for (int val = 10; val <= 95; val += 5) {
                if (val % 25 != 0) continue;
                String valStr = Integer.toString(val);
                char firstChar = inputStr.charAt(0);
                char secondChar = inputStr.charAt(1);
                if (Character.isDigit(firstChar)) {
                    if (Character.isDigit(secondChar)) {
                        if (inputStr.equals(valStr)) totalCount++;
                    } else {
                        if (firstChar == valStr.charAt(0)) totalCount++;
                    }
                } else if (firstChar == '_') {
                    if (Character.isDigit(secondChar)) {
                        if (secondChar == valStr.charAt(1)) totalCount++;
                    } else {
                        totalCount++;
                    }
                } else {
                    if (Character.isDigit(secondChar)) {
                        if (secondChar == valStr.charAt(1)) totalCount++;
                    } else if (secondChar == '_') {
                        totalCount++;
                    }
                }
            }
            System.out.println(totalCount);
            return;
        }

        int startNum = (int) Math.pow(10, length - 1);
        int endNum = (int) Math.pow(10, length);
        int countMatches = 0;

        for (int num = startNum; num < endNum; num += 25) {
            String numStr = Integer.toString(num);
            boolean isValid = true;
            Set<Character> diffChars = new HashSet<>();
            for (int j = 0; j < length; j++) {
                char patternChar = inputStr.charAt(j);
                char digitChar = numStr.charAt(j);
                if (patternChar == '_') continue;
                if (patternChar == 'X') {
                    diffChars.add(digitChar);
                } else if (patternChar != digitChar) {
                    isValid = false;
                    break;
                }
            }
            if (isValid && diffChars.size() < 2) countMatches++;
        }
        System.out.println(countMatches);
        scanner.close();
    }
}
